// [47031 BRINGUP] Master gate for hooks whose target offset is not yet
// verified against the live 47031 process. OFF => the install is SKIPPED
// (no trampoline at a stale address) and Orig is nulled. Flip true / per-
// offset as offsets are confirmed at runtime.
static bool g_gameplayHooks = false;

// [50451 PORT] Address gate. Every image address in this file was re-located in the 50451 PE by byte
// matching (tools/a2port/work50451/resolve2.py -> resolved2.json). A literal that could not be verified is
// written HX_UNRES(0xOLD), which is 0, so base + HX_UNRES(..) lands in the PE-header page. The hook and
// patch helpers refuse that page, so an unresolved address is skipped and logged instead of hooking or
// patching unrelated 50451 code. Call sites that would CALL or dereference one check HxRvaOk first.
#define HX_UNRES(old) 0x0ull
static constexpr bool HxRvaOk(uintptr_t rva) { return rva >= 0x1000; }
static inline bool HxAddrOk(const void* p)
{
    const uintptr_t a = reinterpret_cast<uintptr_t>(p), b = reinterpret_cast<uintptr_t>(GetModuleHandleW(nullptr));
    return a - b >= 0x1000;   // an address outside the module wraps to a huge value -> allowed
}
static inline MH_STATUS HxMhCreate(LPVOID pTarget, LPVOID pDetour, LPVOID* ppOriginal)
{
    if (!HxAddrOk(pTarget))
    {
        if (ppOriginal) *ppOriginal = nullptr;
        printf("[HalcyonA2][RVAGATE] hook skipped: target RVA unresolved for 50451\n");
        return MH_ERROR_NOT_EXECUTABLE;
    }
    return MH_CreateHook(pTarget, pDetour, ppOriginal);
}
#define MH_CreateHook HxMhCreate

static inline MH_STATUS MH_CreateHookG(LPVOID pTarget, LPVOID pDetour, LPVOID* ppOriginal)
{
    if (!g_gameplayHooks) { if (ppOriginal) *ppOriginal = nullptr; return MH_OK; }
    return MH_CreateHook(pTarget, pDetour, ppOriginal);
}
static inline bool HxPageWritable(const void* p)
{
    MEMORY_BASIC_INFORMATION mbi{};
    if (!VirtualQuery(p, &mbi, sizeof(mbi)) || mbi.State != MEM_COMMIT) return false;
    const DWORD w = PAGE_READWRITE | PAGE_WRITECOPY | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY;
    return (mbi.Protect & w) != 0;
}

